import math
    import random
    import time

    LANGUAGE_WRAPPER = 'A deck consists of cards described by {num_attributes} independent attributes. Each attribute can take one of {num_values} values, and every attribute-value combination appears exactly once, so the deck has {num_values}^{num_attributes} cards. A selection of {num_values} distinct cards is called complementary if, for every attribute, the values across the selected cards are either all identical or all pairwise distinct. Among all complementary selections of {num_values} cards, how many have exactly {exact_same_attrs} attributes that are identical across the selection?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose prime p >= 3 for number of values per attribute
primes = [3, 5, 7, 11, 13]
p = rng.choice(primes)
# Choose number of attributes n >= 3
n = rng.randint(3, 7)
# Choose exact_same_attrs s between 1 and n-2 to avoid trivial extremes
if n - 2 >= 1:
    s = rng.randint(1, n - 2)
else:
    # Fallback, though for n>=3 this won't trigger
    s = 1
return {
    'num_attributes': n,
    'num_values': p,
    'exact_same_attrs': s
}

    def verifier(assign):
# Validate keys
required = ['num_attributes', 'num_values', 'exact_same_attrs']
for k in required:
    if k not in assign:
        # Missing slot
        return (False, None)  # missing key
n = assign['num_attributes']
p = assign['num_values']
s = assign['exact_same_attrs']
# Type checks
if not isinstance(n, int) or not isinstance(p, int) or not isinstance(s, int):
    return (False, None)  # types must be integers
# Domain checks
if n < 3:
    return (False, None)  # need at least 3 attributes for nontrivial structure
if p < 3:
    return (False, None)  # must be at least 3 values
# primality check for p
def is_prime(x):
    if x < 2:
        return False
    if x % 2 == 0:
        return x == 2
    d = 3
    while d * d <= x:
        if x % d == 0:
            return False
        d += 2
    return True
if not is_prime(p):
    return (False, None)  # must be prime to ensure field structure for counting
# s must be between 1 and n-2 for difficulty (avoids edge cases), and also <= n-1 for validity
if not (1 <= s <= n - 2):
    return (False, None)
# Compute answer using affine-line classification over GF(p)^n
# Number of complementary p-sets with exactly s attributes identical equals:
# p^{n-1} * C(n, s) * (p-1)^{n - s - 1}
import math
comb = math.comb(n, s)
answer = pow(p, n - 1) * comb * pow(p - 1, n - s - 1)
# Sanity: answer should be a positive integer
if not isinstance(answer, int) or answer <= 0:
    return (False, None)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

